import { Area as RechartsArea } from "recharts";
import { useTheme } from "@theme";
import { clsx } from "clsx";

import { AreaProps } from "../chart.types";
import { useChart } from "../hooks/use-chart";
import { ChartClasses } from "../chart.styles";

const Area = ({ areaIndex = 0, variant = "default", ...props }: AreaProps) => {
  const theme = useTheme();
  const { numCategoricalColors } = useChart();

  const areaProps: AreaProps = { ...props };

  if (variant === "dashed") {
    areaProps.fillOpacity = props.fillOpacity ?? 0;
    areaProps.strokeDasharray = props.strokeDasharray ?? "5 5";
  }

  if (!props.stroke) {
    const colorKey = `${
      (areaIndex % numCategoricalColors) + 1
    }Default` as keyof typeof theme.color.data.categorical;
    areaProps.stroke = theme.color.data.categorical[colorKey];
  }

  if (!props.fill) {
    const colorKey = `${
      (areaIndex % numCategoricalColors) + 1
    }Default` as keyof typeof theme.color.data.categorical;
    areaProps.fill = theme.color.data.categorical[colorKey];
  }

  return (
    <RechartsArea
      strokeWidth={2}
      {...areaProps}
      className={clsx(ChartClasses.area, areaProps.className)}
    />
  );
};

Area.displayName = "Area";

export default Area;
